import os

# [CHANGE 1] Must be set before torch is imported to reduce CUDA memory fragmentation
os.environ["PYTORCH_CUDA_ALLOC_CONF"] = "expandable_segments:True"

import argparse
import json
import re
import sys

import torch
from tqdm import tqdm
from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig


# Remove the reasoning part from a raw model output.
# Depending on the chat template the opening <think> tag is either generated by the model
# or already part of the prompt, so only the closing </think> tag is relied upon.
def strip_thinking(text, thinking_enabled):
    if "</think>" in text:
        return text.rsplit("</think>", 1)[1].strip()
    if thinking_enabled:
        # reasoning never finished (hit the token limit) -> no usable answer
        return ""
    return text.strip()


# Sampling settings: temperature 0.8 as in the earlier pipeline steps (diversity
# between the samples matters); top_p / top_k follow Qwen's recommendations. All overridable.
def default_sampling(thinking):
    if thinking:
        return {"temperature": 0.6, "top_p": 0.95, "top_k": 20}
    return {"temperature": 0.8, "top_p": 0.8, "top_k": 20}


# A response is usable for the next step only if it contains a ```sql ... ``` block
_SQL_BLOCK_RE = re.compile(r"```sql\s*(.*?)\s*```", re.DOTALL)

def has_sql_block(response):
    return _SQL_BLOCK_RE.search(response) is not None


# Keep only the prompts that belong to the first `num_dbs` distinct databases
# (same helper as in synthesize_sql.py; the prompt file is grouped by database).
def select_databases(dataset, num_dbs):
    if num_dbs is None:
        return dataset
    chosen = []
    for data in dataset:
        if data["db_id"] not in chosen:
            if len(chosen) >= num_dbs:
                continue
            chosen.append(data["db_id"])
    chosen = set(chosen)
    return [data for data in dataset if data["db_id"] in chosen]


# clear error for a wrong input path
def check_file(path, what):
    if os.path.isdir(path):
        sys.exit(f"ERROR: --{what} points to a FOLDER, but a file is needed:\n  {os.path.abspath(path)}")
    if not os.path.isfile(path):
        sys.exit(f"ERROR: file for --{what} not found:\n  {os.path.abspath(path)}\n"
                 f"(relative paths are resolved from the folder you start the script in: {os.getcwd()})")


def load_model(model_name, use_4bit=True):
    """Load a Hugging Face causal LM and its tokenizer on the GPU."""
    if not torch.cuda.is_available():
        raise RuntimeError(
            "No GPU found. In Colab: Runtime -> Change runtime type -> T4 GPU, then reconnect."
        )

    tokenizer = AutoTokenizer.from_pretrained(model_name)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    tokenizer.padding_side = "left"  # required for batched generation

    kwargs = {"device_map": "auto"}
    if use_4bit:
        kwargs["quantization_config"] = BitsAndBytesConfig(
            load_in_4bit=True,
            bnb_4bit_quant_type="nf4",
            bnb_4bit_compute_dtype=torch.float16,
        )
    else:
        kwargs["dtype"] = torch.float16  # T4 has no good bf16 support

    model = AutoModelForCausalLM.from_pretrained(model_name, **kwargs)
    model.eval()
    return model, tokenizer


def generate_responses(model, tokenizer, prompts, num_samples=1, batch_size=1, max_new_tokens=2048,
                       max_prompt_tokens=None, thinking=False, greedy=False,
                       temperature=None, top_p=None):
    """
    Generate `num_samples` responses for every prompt.

    - Prompts are sorted by length so each batch has little padding (less memory).
    - If a batch runs out of GPU memory, its prompts are retried one at a time, and the
      samples of a prompt one by one.
    - Samples that still don't fit are skipped (a prompt can end up with fewer responses).

    Returns (responses, stats): responses[i] is the list of raw responses for prompts[i].
    """
    # chat format + thinking switch passed to the chat template
    texts = [
        tokenizer.apply_chat_template(
            [{"role": "user", "content": p}],
            tokenize=False,
            add_generation_prompt=True,
            enable_thinking=thinking,
        )
        for p in prompts
    ]

    lengths = [len(tokenizer(t, add_special_tokens=False).input_ids) for t in texts]
    print(f"Prompt length in tokens: max={max(lengths)}, avg={sum(lengths) / len(lengths):.0f}")

    tok_kwargs = {}
    if max_prompt_tokens:
        tok_kwargs = {"truncation": True, "max_length": max_prompt_tokens}

    # generation settings
    if greedy:
        gen_kwargs = {"do_sample": False}
        num_samples = 1  # identical samples would be pointless
    else:
        rec = default_sampling(thinking)
        gen_kwargs = {
            "do_sample": True,
            "temperature": temperature if temperature is not None else rec["temperature"],
            "top_p": top_p if top_p is not None else rec["top_p"],
            "top_k": rec["top_k"],
        }

    # token ids that mean "the model finished its answer" (used to detect cut-off responses)
    eos = getattr(model.generation_config, "eos_token_id", None)
    eos_ids = set(eos) if isinstance(eos, (list, tuple)) else ({eos} if eos is not None else set())
    if tokenizer.eos_token_id is not None:
        eos_ids.add(tokenizer.eos_token_id)

    order = sorted(range(len(texts)), key=lambda i: lengths[i])
    responses = [[] for _ in texts]
    stats = {"truncated": 0, "skipped": 0}

    def run(batch_idx, n):
        batch = [texts[i] for i in batch_idx]
        inputs = tokenizer(
            batch, return_tensors="pt", padding=True, add_special_tokens=False, **tok_kwargs
        ).to(model.device)

        with torch.no_grad():
            outputs = model.generate(
                **inputs,
                max_new_tokens=max_new_tokens,
                pad_token_id=tokenizer.pad_token_id,
                num_return_sequences=n,
                **gen_kwargs,
            )

        # Drop the prompt tokens and decode only what the model generated.
        # The n samples of one prompt are consecutive rows of `outputs`.
        generated = outputs[:, inputs["input_ids"].shape[1]:]
        decoded = tokenizer.batch_decode(generated, skip_special_tokens=True)
        for k, (text, row) in enumerate(zip(decoded, generated.tolist())):
            responses[batch_idx[k // n]].append(text)
            if not any(t in eos_ids for t in row):
                stats["truncated"] += 1  # ran into max_new_tokens without finishing

    for start in tqdm(range(0, len(order), batch_size), desc="Generating"):
        batch_idx = order[start:start + batch_size]
        try:
            run(batch_idx, num_samples)
        except torch.OutOfMemoryError:
            torch.cuda.empty_cache()
            for i in batch_idx:  # retry one prompt at a time, one sample at a time
                for _ in range(num_samples):
                    try:
                        run([i], 1)
                    except torch.OutOfMemoryError:
                        stats["skipped"] += 1
                        print(f"Skipping a sample of prompt {i} ({lengths[i]} tokens): not enough GPU memory")
                        torch.cuda.empty_cache()
        torch.cuda.empty_cache()

    return responses, stats


def llm_inference(model, dataset, num_samples=1, batch_size=1, max_new_tokens=2048, use_4bit=True,
                  max_prompt_tokens=None, thinking=False, greedy=False,
                  temperature=None, top_p=None):
    """
    Perform LLM inference to generate multiple responses for each prompt in the dataset.

    Args:
        model: Hugging Face model name or local path (e.g. Qwen/Qwen3.5-2B).
        dataset: A list of dictionaries.

    Returns:
        A list of dictionaries, where each dictionary includes the original data and the corresponding generated responses.
    """

    prompts = [data["cot_synthesis_prompt"] for data in dataset]

    #  load the model and generate (replaces the empty `responses_list` placeholder)
    llm, tokenizer = load_model(model, use_4bit=use_4bit)
    raw_responses_list, stats = generate_responses(
        llm, tokenizer, prompts,
        num_samples=num_samples,
        batch_size=batch_size,
        max_new_tokens=max_new_tokens,
        max_prompt_tokens=max_prompt_tokens,
        thinking=thinking,
        greedy=greedy,
        temperature=temperature,
        top_p=top_p,
    )

    #  drop the reasoning part of every response
    responses_list = [
        [strip_thinking(response, thinking) for response in responses]
        for responses in raw_responses_list
    ]

    # format check
    total = sum(len(responses) for responses in responses_list)
    with_sql = sum(has_sql_block(r) for responses in responses_list for r in responses)
    prompts_with_valid = sum(any(has_sql_block(r) for r in responses) for responses in responses_list)
    print(f"Responses: {total} generated, {with_sql} contain a ```sql block, "
          f"{stats['truncated']} cut off by --max_new_tokens, {stats['skipped']} skipped (GPU memory)")
    print(f"Prompts with at least one usable response: {prompts_with_valid}/{len(prompts)}")

    # Initialize an empty list to store the results
    results = []

    # Iterate through the dataset and the corresponding responses
    for data, responses in zip(dataset, responses_list):
        # Add the generated responses to the current data entry
        data["responses"] = responses

        # Append the updated data entry to the results
        results.append(data)

    return results


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument("--model", type=str, default="Qwen/Qwen3.5-2B")  # default ai
    #  new options
    parser.add_argument("--num_samples", type=int, default=1,
                        help="CoT responses per prompt. More samples = higher chance that one is correct, but much slower.")
    parser.add_argument("--batch_size", type=int, default=1)
    parser.add_argument("--max_new_tokens", type=int, default=2048,
                        help="Max generated tokens per response. A CoT is long: raise it (e.g. 4096) if responses get cut off.")
    parser.add_argument("--max_prompt_tokens", type=int, default=None,
                        help="Truncate prompts to this many tokens (cuts off the END of the prompt)")
    parser.add_argument("--thinking", action="store_true",
                        help="Enable Qwen3.5 thinking mode (slower; the hidden reasoning is removed from the output).")
    parser.add_argument("--greedy", action="store_true",
                        help="Deterministic decoding (forces --num_samples 1).")
    parser.add_argument("--temperature", type=float, default=None,
                        help="Overrides the default temperature (0.8).")
    parser.add_argument("--top_p", type=float, default=None)
    parser.add_argument("--num_dbs", type=int, default=None,
                        help="Use prompts from only the first N databases in the input file.")
    parser.add_argument("--limit", type=int, default=None,
                        help="Only process the first N prompts (quick test run)")
    parser.add_argument("--no_4bit", action="store_true", help="Load in fp16 instead of 4-bit")
    parser.add_argument("--input", default="cot_synthesis/prompts/cot_synthesis_prompts.json")
    parser.add_argument("--output", default="cot_synthesis/results/cot_synthesis.json")

    opt = parser.parse_args()
    print(opt)

    check_file(opt.input, "input")
    with open(opt.input, encoding="utf-8") as f:  #  utf-8
        input_dataset = json.load(f)
    input_dataset = select_databases(input_dataset, opt.num_dbs)
    if opt.limit:
        input_dataset = input_dataset[:opt.limit]
    print(f"{len({d['db_id'] for d in input_dataset})} databases, {len(input_dataset)} prompts selected")
    output_file = opt.output

    results = llm_inference(
        opt.model, input_dataset,
        num_samples=opt.num_samples,
        batch_size=opt.batch_size,
        max_new_tokens=opt.max_new_tokens,
        use_4bit=not opt.no_4bit,
        max_prompt_tokens=opt.max_prompt_tokens,
        thinking=opt.thinking,
        greedy=opt.greedy,
        temperature=opt.temperature,
        top_p=opt.top_p,
    )

    # create the results folder if needed
    os.makedirs(os.path.dirname(os.path.abspath(output_file)), exist_ok=True)
    with open(output_file, "w", encoding="utf-8") as f:
        f.write(json.dumps(results, indent=2, ensure_ascii=False))
    print(f"Saved {len(results)} entries to {output_file}")